// Extract and validate VAPI call data
const items = $input.all();
const callData = items[0].json;

// Extract call information
const extractedData = {
  call_id: callData.call?.id || 'unknown',
  phone_number: callData.call?.phoneNumberId || callData.phoneNumber,
  customer_number: callData.call?.customer?.number || callData.customer?.number,
  transcript: callData.transcript || '',
  assistant_message: callData.message?.content || '',
  call_status: callData.call?.status || 'unknown',
  timestamp: new Date().toISOString(),

  // Extract healthcare search intent from transcript or assistant message
  search_query: callData.message?.content || callData.transcript || '',

  // VAPI function call data if present
  function_call: callData.message?.function_call || null,

  // Call metadata
  call_duration: callData.call?.duration || 0,
  call_direction: callData.call?.type || 'inbound',

  // Customer contact preferences and details
  customer_email: callData.customer?.email || null,
  customer_name: callData.customer?.name || 'Customer',
  customer_wants_email: false,
  customer_wants_sms: false
};

// Check if customer requested email or SMS
const messageContent = (callData.message?.content || '').toLowerCase();
if (messageContent.includes('email') || messageContent.includes('send me')) {
  extractedData.customer_wants_email = true;
}
if (messageContent.includes('sms') || messageContent.includes('text') || messageContent.includes('message')) {
  extractedData.customer_wants_sms = true;
}

// Log the received data for debugging
console.log('VAPI Call Data Received:', JSON.stringify(extractedData, null, 2));

return [{ json: extractedData }];

// Prepare healthcare search parameters from VAPI function call
const items = $input.all();
const callData = items[0].json;

let searchParams = {
  query: 'general search',
  max_results: 5,
  location: null,
  specialty: null,
  provider_type: null
};

// Extract function call parameters if available
if (callData.function_call && callData.function_call.arguments) {
  const args = typeof callData.function_call.arguments === 'string' 
    ? JSON.parse(callData.function_call.arguments)
    : callData.function_call.arguments;

  searchParams.query = args.query || callData.search_query || 'general search';
  searchParams.max_results = args.max_results || 5;
  searchParams.location = args.location || null;
  searchParams.specialty = args.specialty || null;
  searchParams.provider_type = args.provider_type || null;
}

// Prepare the complete call context
const enhancedData = {
  ...callData,
  search_params: searchParams,
  api_endpoint: '/premier-health/search',
  request_timestamp: new Date().toISOString()
};

console.log('Prepared Search Parameters:', JSON.stringify(searchParams, null, 2));

return [{ json: enhancedData }];

// Prepare escalation parameters from VAPI function call
const items = $input.all();
const callData = items[0].json;

let escalationParams = {
  customer_name: 'Customer',
  customer_email: null,
  customer_phone: null,
  search_query: '',
  location_searched: '',
  issue_description: ''
};

// Extract function call parameters if available
if (callData.function_call && callData.function_call.arguments) {
  const args = typeof callData.function_call.arguments === 'string' 
    ? JSON.parse(callData.function_call.arguments)
    : callData.function_call.arguments;

  escalationParams.customer_name = args.customer_name || callData.customer_name || 'Customer';
  escalationParams.customer_email = args.customer_email || callData.customer_email;
  escalationParams.customer_phone = args.customer_phone || callData.phone_number;
  escalationParams.search_query = args.search_query || callData.search_query;
  escalationParams.location_searched = args.location_searched;
  escalationParams.issue_description = args.issue_description || '';
}

// Prepare the complete escalation context
const enhancedData = {
  ...callData,
  escalation_params: escalationParams,
  api_endpoint: '/premier-health/escalate-to-support',
  request_timestamp: new Date().toISOString()
};

console.log('Prepared Escalation Parameters:', JSON.stringify(escalationParams, null, 2));

return [{ json: enhancedData }];

// Format the API response for VAPI with escalation check
const items = $input.all();
const apiResponse = items[0].json;
const originalData = items[0].json;

// Extract provider data
const providers = apiResponse.data?.providers || [];
const totalFound = apiResponse.data?.total_found || 0;
const voiceResponse = apiResponse.data?.voice_response || 'No providers found.';

// Check if no providers found and location-specific search
const shouldEscalate = providers.length === 0 && originalData.search_params?.location;

// Store provider data for potential email/SMS use
const providerData = providers.map(provider => ({
  name: provider.name,
  specialty: provider.specialty,
  location: provider.location,
  phone: provider.phone,
  address: provider.address,
  rating: provider.rating
}));

// Create VAPI response format
let vapiResponse;

if (shouldEscalate) {
  // Suggest escalation when no providers found in specific location
  vapiResponse = {
    message: {
      type: 'assistant',
      content: `I couldn't find any providers in ${originalData.search_params.location} at the moment. Would you like me to escalate this to our support team? They can review our database and call you back within 24 hours with more options. I'll need your name, email, and phone number to create a support ticket.`,
      function_call_result: {
        success: false,
        data: {
          providers: [],
          total_found: 0,
          escalation_suggested: true,
          location_searched: originalData.search_params.location
        }
      }
    }
  };
} else {
  // Normal response when providers found
  vapiResponse = {
    message: {
      type: 'assistant',
      content: voiceResponse + (providers.length > 0 ? ' Would you like me to send this information to your email or phone?' : ''),
      function_call_result: {
        success: apiResponse.success || false,
        data: {
          providers: providers.slice(0, 3), // Limit for voice response
          total_found: totalFound,
          search_completed: true
        }
      }
    }
  };
}

// Include original call data and provider data for follow-up actions
const enhancedResponse = {
  ...originalData,
  vapi_response: vapiResponse,
  provider_data: providerData,
  providers_found_count: providers.length,
  search_successful: apiResponse.success,
  escalation_suggested: shouldEscalate
};

console.log('VAPI Response Prepared:', JSON.stringify(vapiResponse, null, 2));

return [{ json: enhancedResponse }];

// Format the escalation response for VAPI
const items = $input.all();
const escalationResponse = items[0].json;
const originalData = items[0].json;

// Extract escalation result
const escalationData = escalationResponse.data || {};
const voiceResponse = escalationData.voice_response || 'Your request has been escalated to our support team.';

// Create VAPI response format for escalation
const vapiResponse = {
  message: {
    type: 'assistant',
    content: voiceResponse,
    function_call_result: {
      success: escalationResponse.success || false,
      data: {
        escalated: escalationData.escalated || false,
        ticket_id: escalationData.ticket_id,
        estimated_callback: escalationData.estimated_callback,
        escalation_completed: true
      }
    }
  }
};

// Include original call data for analytics
const enhancedResponse = {
  ...originalData,
  vapi_response: vapiResponse,
  escalation_result: escalationData,
  escalation_successful: escalationResponse.success
};

console.log('Escalation VAPI Response Prepared:', JSON.stringify(vapiResponse, null, 2));

return [{ json: enhancedResponse }];
